/**
 * MusterGo backend — Express API for the SCCCI admin dashboard.
 *
 * Run:
 *   npm install
 *   npm run dev        # http://localhost:4000  (needs DATABASE_URL in .env — PostgreSQL)
 *
 * The data layer (data.js) talks to PostgreSQL and is asynchronous, so the route
 * handlers are async and `await` it. The server only starts listening AFTER the
 * database connection + schema are ready (see the bottom of the file).
 *
 * This file is deliberately just Express bootstrap + middleware + mounting
 * (2026-07-21 split, mirroring the earlier data.js -> db/*.js split). JQ's own
 * base routes now live in backend/routes/{auth,accounts,dashboard,delegates,
 * history}.js — see the TEAMMATE ZONE below for where feature routers mount.
 */

import "dotenv/config"; // loads backend/.env into process.env — MUST be first
import express from "express";
import cors from "cors";
import { initDb } from "./data.js";
import { applyCheckpointLateCutoff, resetArrivedBeforeNextCheckpoint } from "./routes/dashboard/checkpoints.js";
import { syncTripDayOf } from "./db/dashboard.js";

const app = express();
const PORT = process.env.PORT || 4000;

// Allow the frontend origin. In production set FRONTEND_URL (e.g. the Vercel
// URL) so only your own site can call the API with credentials. Without it we
// fall back to reflecting any origin, which is fine for the local Vite dev
// proxy but NOT safe to leave that way in production — warn loudly so it isn't
// forgotten (mirrors the JWT_SECRET warning in auth.js).
if (!process.env.FRONTEND_URL) {
  console.warn(
    "  WARNING: FRONTEND_URL is not set in backend/.env — CORS will allow ANY origin.\n" +
    "  Set FRONTEND_URL to your deployed frontend URL before deploying anywhere public.\n"
  );
}
app.use(cors({ origin: process.env.FRONTEND_URL || true, credentials: true }));

/* The Excel export can carry chart PNGs (2026-07-29 — charts are embedded as
 * pictures on their own sheet; see routes/export.js's sanitizeChartImages), and
 * a handful of base64 images comfortably exceeds express.json()'s 100kb
 * default. Raised for THAT ONE ROUTE ONLY, deliberately: the global limit stays
 * tight, because a large-body allowance is exactly the lever an attacker uses
 * to exhaust memory, and every other endpoint in this app handles small JSON.
 *
 * Order matters — this must run BEFORE the global parser below. express.json()
 * no-ops when a body has already been parsed (it checks `req._body`), so the
 * general parser simply skips a request this one has handled; the reverse order
 * would let the 100kb limit reject the request first. Matched on an exact path
 * shape rather than a prefix so it can't be widened by a crafted URL. */
const exportJson = express.json({ limit: "12mb" });
app.use((req, res, next) => {
  if (req.method === "POST" && /^\/api\/trips\/[^/]+\/export\/?$/.test(req.path)) {
    return exportJson(req, res, next);
  }
  return next();
});
app.use(express.json());

app.use((req, _res, next) => {
  console.log(`${new Date().toLocaleTimeString()}  ${req.method} ${req.url}`);
  next();
});

/* ---- Health ------------------------------------------------------------- */
app.get("/api/health", (_req, res) => res.json({ ok: true, service: "mustergo-backend" }));

/* ---- JQ's base routes ----------------------------------------------------
 * Auth, Account control, Trips/Dashboard reads, Delegate CRUD (+ photo),
 * and the History tracker. See backend/routes/*.js for each domain.
 * ------------------------------------------------------------------------- */
import authRouter from "./routes/auth.js";
app.use(authRouter);

import accountsRouter from "./routes/accounts.js";
app.use(accountsRouter);

import dashboardRouter from "./routes/dashboard/dashboard.js";
app.use(dashboardRouter);

import delegatesRouter from "./routes/dashboard/delegates.js";
app.use(delegatesRouter);

import historyRouter from "./routes/dashboard/history.js";
app.use(historyRouter);

import checkpointsRouter from "./routes/dashboard/checkpoints.js";
app.use(checkpointsRouter);

import escalationsRouter from "./routes/dashboard/escalations.js";
app.use(escalationsRouter);

import announcementsRouter from "./routes/announcements.js";
app.use(announcementsRouter);

import guideVideoRouter from "./routes/guideVideo.js";
app.use(guideVideoRouter);

import roomAssignRouter from "./routes/dashboard/roomAssign.js";
app.use(roomAssignRouter);

